+                expr instanceof CallExpression
+                        ? FILTERS.get(((CallExpression) expr).getFunctionDefinition())
+                        : null;
+        if (extractor == null) {
+            LOG.debug(
+                    "Unsupported predicate [{}] cannot be pushed into savepoint key filter.", expr);
+            return null;
+        }
+        return extractor.apply(this, (CallExpression) expr);
+    }
