+    }
+
+    // -------------------------------------------------------------------------
+    //  Range
+    // -------------------------------------------------------------------------
+
+    @Nullable
+    private SavepointKeyFilter fromAnd(CallExpression call) {
+        SavepointKeyFilter merged = null;
+        for (ResolvedExpression arg : call.getResolvedChildren()) {
